import { useEffect, useState } from 'react';
import { getStats } from '../services/statsService';

export const useHomeData = () => {
  const [stats, setStats] = useState({
    tools: 17,
    services: 4,
    support: 30,
    satisfaction: 100
  });

  const [heroStats, setHeroStats] = useState({
    s1n: '10+',
    s1l: 'AI Tools Mastered',
    s2n: '4',
    s2l: 'Core Services',
    s3n: '1',
    s3l: 'Focused Mission'
  });

  useEffect(() => {
    const fetchStats = async () => {
      try {
        const response = await getStats();
        if (response.data) {
          setStats({
            tools: response.data.tools || 17,
            services: response.data.services || 4,
            support: response.data.support || 30,
            satisfaction: response.data.satisfaction || 100
          });
          setHeroStats({
            s1n: response.data.stat1Number || '10+',
            s1l: response.data.stat1Label || 'AI Tools Mastered',
            s2n: response.data.stat2Number || '4',
            s2l: response.data.stat2Label || 'Core Services',
            s3n: response.data.stat3Number || '1',
            s3l: response.data.stat3Label || 'Focused Mission'
          });
        }
      } catch (error) {
        console.error('Error fetching stats:', error);
      }
    };

    fetchStats();
  }, []);

  return { stats, heroStats };
};
